    /// Where the needles are.
    pub fn needles(&self, f: Frame) -> Mask {
        Mask::from_shape(f, self.needle_shape(Shape::new()))
    }

    /// The leader and every bough (the wood, needles or not).
    pub fn wood(&self, f: Frame) -> Mask {
